    for(let j=0;j<3;j++)for(let i=0;i<3;i++){const a=base+j*4+i,b=a+1,c=a+4,e=c+1;indices.push(...(sign>0?[a,b,c,b,e,c]:[a,c,b,b,c,e]));}
